import { readFileSync } from 'node:fs';
import { Scout as CoreScout } from './scout';
export class Scout extends CoreScout {
  constructor(opts) {
    const registry = typeof opts.intentRegistry === 'string'
      ? JSON.parse(readFileSync(opts.intentRegistry, 'utf8'))
      : opts.intentRegistry;
    super({ ...opts, intentRegistry: registry });
  }
}
