:host {
  display: block;
  padding: 32px 16px 56px;
}

.shell {
  width: min(100%, 640px);
  margin: 0 auto;
}

.card {
  padding: clamp(20px, 4vw, 36px);
  border: 1px solid rgb(255 255 255 / 70%);
  border-radius: 24px;
  background: rgb(255 255 255 / 92%);
  box-shadow: var(--shadow);
  backdrop-filter: blur(12px);
}

.header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 24px;
}

.eyebrow {
  margin: 0 0 6px;
  color: var(--accent);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: clamp(1.9rem, 5vw, 2.6rem);
  letter-spacing: -0.04em;
  line-height: 1;
}

.remaining {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
  white-space: nowrap;
}

.remaining strong {
  color: var(--text);
  font-size: 1.15rem;
}

.task-list {
  display: grid;
  gap: 8px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.empty {
  padding: 44px 16px 40px;
  text-align: center;
}

.empty-icon {
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  margin: 0 auto 14px;
  border-radius: 50%;
  background: var(--accent-soft);
  color: var(--accent);
  font-size: 1.5rem;
  font-weight: 800;
}

.empty-title {
  margin: 0 0 6px;
  font-weight: 700;
}

.empty-hint {
  margin: 0;
  color: var(--muted);
  font-size: 0.92rem;
}

.footer {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 22px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.82rem;
}

.dot {
  opacity: 0.5;
}

@media (max-width: 480px) {
  :host {
    padding: 16px 12px 32px;
  }

  .header {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }
}

:root {
  color-scheme: light;
  --bg: #f4f6fb;
  --surface: #fff;
  --text: #161b26;
  --muted: #667085;
  --line: #e4e7ec;
  --accent: #4f46e5;
  --accent-soft: #eef2ff;
  --success: #0f9f6e;
  --danger: #d92d20;
  --shadow: 0 24px 60px -28px rgb(22 27 38 / 35%);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
}

body {
  background:
    radial-gradient(900px 500px at 15% -10%, #e0e7ff 0%, transparent 60%),
    radial-gradient(700px 400px at 100% 0%, #ccfbf1 0%, transparent 55%), var(--bg);
  color: var(--text);
  font-family:
    ui-sans-serif,
    system-ui,
    -apple-system,
    'Segoe UI',
    Roboto,
    Helvetica,
    Arial,
    sans-serif;
  -webkit-font-smoothing: antialiased;
}

button,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

